window.__SD=(window.__SD||[]).concat([{"slug": "boaz-barak", "name": "Boaz Barak", "category": "lab-safety", "current_role": "Member of Technical Staff, alignment team, OpenAI; Catalyst Professor of Computer Science (part-time), Harvard (as of 2026)", "orgs_history": ["OpenAI alignment team (Jan 2024–)", "Harvard University, Gordon McKay Professor of CS (2016–; part-time Catalyst Professor since 2025)", "Microsoft Research New England, principal researcher", "Princeton University, associate professor"], "country": "Israel / United States", "known_for": "Theoretical computer scientist (cryptography, complexity) who joined OpenAI's alignment team and teaches Harvard's first AI safety course; author of the Windows On Theory blog.", "bio": "Boaz Barak is an Israeli-American theoretical computer scientist with a PhD from the Weizmann Institute, known for work on cryptography — including the impossibility of program obfuscation — computational complexity and the sum-of-squares method, and as co-author of the textbook 'Computational Complexity: A Modern Approach'. After positions at Princeton and Microsoft Research he became the Gordon McKay Professor of Computer Science at Harvard, and an ACM Fellow in 2022. In January 2024 he left his tenured post to join OpenAI's alignment team, working on safety for widely used models including research on deliberative alignment, chain-of-thought monitoring and 'confessions'. Since fall 2025 he has been back at Harvard part-time as a Catalyst Professor teaching its first AI safety course while remaining at OpenAI. His blog posts compare OpenAI's Model Spec with Claude's constitution and sketch how the AGI transition could go badly, with particular concern about concentration of power.", "key_ideas": ["intent vs. value alignment; alignment vs. safeguards", "concentration of power risks", "chain-of-thought monitoring / confessions", "model specs and constitutions"], "key_works": [{"title": "On the (Im)possibility of Obfuscating Programs", "year": 2001, "url": "https://link.springer.com/chapter/10.1007/3-540-44647-8_1"}, {"title": "Deep Double Descent", "year": 2019, "url": "https://arxiv.org/abs/1912.02292"}, {"title": "Trading Inference-Time Compute for Adversarial Robustness", "year": 2025, "url": "https://arxiv.org/abs/2501.18841"}, {"title": "Thoughts on Claude's Constitution", "year": 2026, "url": "https://windowsontheory.org/2026/01/27/thoughts-on-claudes-constitution/"}, {"title": "It's 2030 and we fucked up. How did it happen?", "year": 2026, "url": "https://windowsontheory.org/2026/07/13/its-2030-and-we-fucked-up-how-did-it-happen/"}], "quotes": [{"text": "I am particularly concerned about questions regarding concentration of power. A future in which we humanity is under the control of either AI or a small group of unelected humans is not a good future in my books, even if we are materially well off.", "context": "Blog 'It’s 2030 and we fucked up. How did it happen?', July 2026", "source_url": "https://windowsontheory.org/2026/07/13/its-2030-and-we-fucked-up-how-did-it-happen/"}, {"text": "Most importantly, how AI should be deployed in government, which decisions it should make, and how it will be overseen are decisions that should arise from the democratic process, not AI labs.", "context": "Same post, July 2026", "source_url": "https://windowsontheory.org/2026/07/13/its-2030-and-we-fucked-up-how-did-it-happen/"}, {"text": "I don’t think there is one simple answer, and neither extreme is likely to lead to good results.", "context": "Same post, on the control-vs-distribution tradeoff", "source_url": "https://windowsontheory.org/2026/07/13/its-2030-and-we-fucked-up-how-did-it-happen/"}, {"text": "I am glad that Anthropic and OpenAI are not pursuing the exact same approaches– I think trying out a variety of approaches, sharing as much as we can, and having robust monitoring and evaluation, is the way to go.", "context": "'Thoughts on Claude’s Constitution', Jan 2026", "source_url": "https://windowsontheory.org/2026/01/27/thoughts-on-claudes-constitution/"}], "interviews": [{"title": "Harvard’s Computer Science Faculty Keep Heading to Industry (profile/interview)", "outlet": "The Harvard Crimson", "year": 2026, "url": "https://www.thecrimson.com/article/2026/2/24/seas-faculty-ai/"}, {"title": "AI Is a Meteor. Don’t Be a Dinosaur. (op-ed)", "outlet": "The Harvard Crimson", "year": 2026, "url": "https://www.thecrimson.com/article/2026/5/28/barak-harvard-commencement-ai"}, {"title": "CS 2881 Fall 26: Lecture 1: Introduction (AI safety course)", "outlet": "Windows On Theory", "year": 2026, "url": "https://windowsontheory.org/2026/09/22/cs-2881-fall-26-lecture-1-introduction/"}], "links": {"website": "https://www.boazbarak.org/", "x": "https://x.com/boazbaraktcs", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Boaz_Barak", "github": "https://github.com/boazbk", "substack": "https://windowsontheory.org/"}, "p_doom_or_stance": null, "honours": null, "photo": "boaz-barak.jpg"}, {"slug": "johannes-heidecke", "name": "Johannes Heidecke", "category": "lab-safety", "current_role": "Former Head of Safety Systems, OpenAI (left July 2026 after a safety/research reorganization); next role not publicly announced (as of Oct 2026)", "orgs_history": ["OpenAI, Head of Safety Systems (2024–Jul 2026)", "OpenAI, AI safety analyst / researcher (2021–2024)"], "country": "Germany", "known_for": "Ran OpenAI's Safety Systems team (preparedness evals, rule-based rewards, bio-risk safeguards) after Lilian Weng; departed in July 2026.", "bio": "Johannes Heidecke is a German AI safety researcher who joined OpenAI in 2021 as an AI safety analyst and in 2024 succeeded Lilian Weng as head of Safety Systems. His team covered model alignment, rule-based reward systems, refusals and the company's Preparedness Framework evaluations for dangerous capabilities. In June 2025 he told Axios that OpenAI expected successors of its o3 reasoning model to reach the 'high' biological-risk classification, explaining that the worry was 'novice uplift' — helping non-experts replicate known threats — and that safeguards needed 'near perfection'. In a 2025 Die Zeit profile he described OpenAI's approach as gradual, iterative deployment. In July 2026, as OpenAI folded its safety teams under Mia Glaese as VP of research and safety, he told staff he was leaving; Saachi Jain became interim head of Safety Systems. He has made no public statement on his departure.", "key_ideas": ["preparedness evaluations", "bio-risk 'novice uplift'", "rule-based rewards", "iterative deployment"], "key_works": [{"title": "Rule Based Rewards for Language Model Safety (co-author)", "year": 2024, "url": "https://arxiv.org/abs/2411.01111"}, {"title": "Deliberative Alignment: Reasoning Enables Safer Language Models (co-author)", "year": 2024, "url": "https://arxiv.org/abs/2412.16339"}, {"title": "Preparing for future AI capabilities in biology (OpenAI)", "year": 2025, "url": "https://openai.com/index/preparing-for-future-ai-capabilities-in-biology/"}], "quotes": [{"text": "expecting some of the successors of our o3 (reasoning model) to hit that level.", "context": "Axios interview on biological-risk classification, June 2025, as quoted by Fortune", "source_url": "https://fortune.com/2025/06/19/openai-future-models-higher-risk-aiding-bioweapons-creation"}, {"text": "We’re not yet in the world where there’s like novel, completely unknown creation of bio threats that have not existed before,", "context": "Same interview, June 2025 (via Fortune)", "source_url": "https://fortune.com/2025/06/19/openai-future-models-higher-risk-aiding-bioweapons-creation"}, {"text": "We are more worried about replicating things that experts already are very familiar with.", "context": "Same interview, June 2025 (via Fortune)", "source_url": "https://fortune.com/2025/06/19/openai-future-models-higher-risk-aiding-bioweapons-creation"}, {"text": "We basically need, like, near perfection.", "context": "On the reliability bioweapon safeguards require, June 2025 (via Fortune and SiliconANGLE)", "source_url": "https://siliconangle.com/2025/06/19/openai-exec-warns-growing-risk-ai-aid-biological-weapons-development/"}], "interviews": [{"title": "OpenAI warns its future models will have a higher risk of aiding bioweapons development", "outlet": "Fortune (citing Axios)", "year": 2025, "url": "https://fortune.com/2025/06/19/openai-future-models-higher-risk-aiding-bioweapons-creation"}, {"title": "Kritiker fürchten, dass OpenAI die Risiken der Technologie kleinredet (profile)", "outlet": "Die Zeit", "year": 2025, "url": "https://www.zeit.de/2025/20/openai-chatgpt-kuenstliche-intelligenz-forschung-technologie/seite-3"}, {"title": "OpenAI's Head of Safety Is Leaving the Company", "outlet": "WIRED", "year": 2026, "url": "https://www.wired.com/story/openai-head-of-safety-leaving"}], "links": {"website": "", "x": "", "scholar": "https://scholar.google.com/citations?hl=en&user=VXzrmIEAAAAJ", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": ""}, {"slug": "joshua-achiam", "name": "Joshua Achiam", "category": "lab-safety", "current_role": "Former OpenAI Chief Futurist (left July 2026); reported Non-Resident Senior Fellow at the Institute for Progress and the Foundation for American Innovation from Oct 2026 (unverified)", "orgs_history": ["OpenAI, Chief Futurist (Feb–Jul 2026)", "OpenAI, Head of Mission Alignment (Sep 2024–Feb 2026)", "OpenAI, research scientist in AI safety (2017–2024)", "UC Berkeley, PhD in EECS"], "country": "United States", "known_for": "Author of OpenAI's 'Spinning Up in Deep RL' and Constrained Policy Optimization; led OpenAI's Mission Alignment team, then became its Chief Futurist.", "bio": "Joshua Achiam earned BS degrees in physics and aerospace engineering at the University of Florida and a PhD in EECS at UC Berkeley, where he developed Constrained Policy Optimization for safe reinforcement learning. He joined OpenAI as an intern in 2017 and as a research scientist that December, working on AI safety research and operations, AI impacts research and educational resources including 'Spinning Up in Deep RL', and co-authoring the GPT-4 technical report. In September 2024 he was named Head of Mission Alignment, a team meant to help staff and the public understand OpenAI's mission. When that team was disbanded in February 2026 he became OpenAI's Chief Futurist, studying how the world will change in response to AI and AGI, and he testified for OpenAI in the May 2026 Musk v. Altman trial. He left OpenAI in July 2026 after nearly nine years, writing that it 'feels possible to work on the mission from outside the walls of a frontier lab'.", "key_ideas": ["safe RL / constrained policy optimization", "mission alignment (AGI benefiting all of humanity)", "futures studies of AGI", "AI impacts on society"], "key_works": [{"title": "Constrained Policy Optimization", "year": 2017, "url": "https://arxiv.org/abs/1705.10528"}, {"title": "Spinning Up in Deep RL", "year": 2018, "url": "https://spinningup.openai.com/"}, {"title": "Benchmarking Safe Exploration in Deep Reinforcement Learning (Safety Gym)", "year": 2019, "url": "https://cdn.openai.com/safexp-short.pdf"}, {"title": "Introducing Our Chief Futurist", "year": 2026, "url": "https://openaiglobalaffairs.substack.com/p/introducing-our-chief-futurist"}], "quotes": [{"text": "The past is definite, written—often literally—in stone. The future is a different story: undetermined, unfinished, and malleable to those with a will to change it, but extraordinarily difficult to predict with certainty.", "context": "'Introducing Our Chief Futurist', OpenAI Global Affairs newsletter, Feb 2026", "source_url": "https://openaiglobalaffairs.substack.com/p/introducing-our-chief-futurist"}, {"text": "The agricultural revolution unfolded over millennia, the industrial revolution over centuries, the internet revolution over decades, and now an intelligence revolution is poised to transform the world over just a few years.", "context": "Same post, Feb 2026", "source_url": "https://openaiglobalaffairs.substack.com/p/introducing-our-chief-futurist"}, {"text": "The future of humanity depends on the choices we make together about AGI and superintelligence.", "context": "X post announcing his departure from OpenAI, July 2026 (via The Verge)", "source_url": "https://www.theverge.com/ai-artificial-intelligence/962540/openais-chief-futurist-is-leaving-the-company-after-nine-years"}, {"text": "I believe we can get to a world of peace, unprecedented prosperity, and unimaginable possibilities, social and scientific. Whatever I do next, I will continue to work with you on making this vision real.", "context": "Farewell message to OpenAI staff, July 2026 (via WIRED)", "source_url": "https://www.wired.com/story/openai-chief-futurist-joshua-achiam-is-leaving-the-company"}], "interviews": [{"title": "OpenAI's Joshua Achiam: Did We Already Reach AGI?", "outlet": "a16z Podcast (with Theo Jaffee)", "year": 2026, "url": "https://a16z.com/podcast/openais-joshua-achiam-did-we-already-reach-agi/"}, {"title": "Event Replay: OpenAI's Chief Futurist on AGI and What's Next", "outlet": "OpenAI Forum", "year": 2026, "url": "https://forum.openai.com/public/videos/event-replay-openais-chief-futurist-on-agi-and-whats-next-2026-02-26"}, {"title": "Extraordinary. Joshua Achiam on Curiosity, Craft, and Finding Your Own Voice", "outlet": "ChatGPT for Education (OpenAI)", "year": 2026, "url": "https://edunewsletter.openai.com/p/extraordinary-joshua-achiam"}], "links": {"website": "https://jachiam.github.io/", "x": "https://x.com/jachiam0", "scholar": "", "wikipedia": "", "github": "https://github.com/jachiam", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "joshua-achiam.jpg"}, {"slug": "daniel-kokotajlo", "name": "Daniel Kokotajlo", "category": "lab-safety", "current_role": "Executive Director, AI Futures Project (as of 2026)", "orgs_history": ["AI Futures Project, co-founder & executive director (2024–)", "OpenAI, governance/forecasting researcher (2022–2024)", "AI Impacts / Center on Long-Term Risk (researcher)", "UNC Chapel Hill, philosophy MA/PhD studies"], "country": "United States", "known_for": "Ex-OpenAI forecaster who forfeited equity to criticise the company; lead author of the AI 2027 scenario and 'AI 2040: Plan A'.", "bio": "Daniel Kokotajlo studied philosophy at Notre Dame and UNC Chapel Hill before working on AI forecasting. His 2021 essay 'What 2026 Looks Like' was later judged notably prescient. He joined OpenAI's governance team in 2022 to forecast AI progress and resigned in April 2024, saying he had lost confidence the company would behave responsibly; he initially refused to sign a non-disparagement agreement at the risk of losing vested equity, helping force OpenAI to change its exit policy, and co-organised the June 2024 'Right to Warn' letter. He then founded the Berkeley-based nonprofit AI Futures Project, whose April 2025 scenario AI 2027 depicted a month-by-month race to superintelligence. In July 2026 the team published 'AI 2040: Plan A', a normative plan for a verified US–China slowdown that delays superintelligence to 2040. He testified to the US Senate in September 2026 and to a UK parliamentary committee in October 2026.", "key_ideas": ["AI 2027 scenario", "automated AI R&D / intelligence explosion", "verifiable US–China slowdown ('Plan A')", "whistleblower protections / right to warn", "eval awareness and declining monitorability"], "key_works": [{"title": "What 2026 Looks Like", "year": 2021, "url": "https://www.lesswrong.com/posts/6Xgy6CAf2jqHhynHL/what-2026-looks-like"}, {"title": "A Right to Warn about Advanced Artificial Intelligence (co-organiser)", "year": 2024, "url": "https://righttowarn.ai/"}, {"title": "AI 2027", "year": 2025, "url": "https://ai-2027.com/"}, {"title": "AI 2040: Plan A", "year": 2026, "url": "https://blog.aifutures.org/p/ai-2040-plan-a"}], "quotes": [{"text": "I resigned partly due to losing confidence that the company would behave responsibly, and partly so I could speak more freely about the industry and where it is headed.", "context": "US Senate testimony, 30 Sept 2026", "source_url": "https://blog.aifutures.org/p/senate-testimony-sept-2026"}, {"text": "Anthropic and OpenAI are racing each other towards superintelligence — that is, towards training AI systems that are better than the best humans at everything, while also being faster and cheaper.", "context": "US Senate testimony, Sept 2026", "source_url": "https://blog.aifutures.org/p/senate-testimony-sept-2026"}, {"text": "I personally would guess about 50% chance by end of 2028.", "context": "Senate testimony, on when AI companies will automate the whole AI research process", "source_url": "https://blog.aifutures.org/p/senate-testimony-sept-2026"}, {"text": "In fact I’d say that the field is more like psychology than engineering.", "context": "Senate testimony, on the science of aligning AI agents", "source_url": "https://blog.aifutures.org/p/senate-testimony-sept-2026"}, {"text": "It’s called Plan A because it’s a recommendation, not a prediction. It’s what we think should happen, not what will happen, though we think it’s plausible enough to aim for.", "context": "'AI 2040: Plan A' launch post, July 2026", "source_url": "https://blog.aifutures.org/p/ai-2040-plan-a"}], "interviews": [{"title": "AI 2027: month-by-month model of intelligence explosion — Scott Alexander & Daniel Kokotajlo", "outlet": "Dwarkesh Podcast", "year": 2025, "url": "https://www.dwarkesh.com/p/scott-daniel"}, {"title": "Scaling Laws: Daniel Kokotajlo on AI 2040: Plan A", "outlet": "Lawfare", "year": 2026, "url": "https://www.lawfaremedia.org/article/scaling-laws--daniel-kokotajlo-on-ai-2040--plan-a"}, {"title": "Daniel Kokotajlo on AI 2040 and Plan A", "outlet": "Palisade Podcast", "year": 2026, "url": "https://palisaderesearch.org/blog/palisade-podcast-daniel-kokotajlo"}, {"title": "Senate Testimony Sept 2026", "outlet": "US Senate (via AI Futures Project blog)", "year": 2026, "url": "https://blog.aifutures.org/p/senate-testimony-sept-2026", "youtube_id": "LfDXO4VjUbE"}], "links": {"website": "https://ai-futures.org/", "x": "https://x.com/DKokotajlo", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Daniel_Kokotajlo", "github": "", "substack": "https://blog.aifutures.org/"}, "p_doom_or_stance": "Expects ~50% chance AI companies fully automate AI research by end of 2028 (Senate testimony, Sept 2026).", "honours": null, "photo": "daniel-kokotajlo.jpg"}, {"slug": "leopold-aschenbrenner", "name": "Leopold Aschenbrenner", "category": "lab-safety", "current_role": "Founder and CIO, Situational Awareness LP (AI-focused investment fund; as of Oct 2026, rebuilding after a July 2026 near-collapse)", "orgs_history": ["Situational Awareness LP, founder & CIO (2024–)", "OpenAI Superalignment team (2023–Apr 2024; fired over an alleged leak, which he disputes)", "FTX Future Fund (2022)", "Columbia University, BA economics (valedictorian at 19)"], "country": "Germany", "known_for": "Author of the 2024 essay series 'Situational Awareness: The Decade Ahead'; ex-OpenAI superalignment researcher turned AI hedge-fund manager.", "bio": "Leopold Aschenbrenner is a German-born researcher and investor who graduated as valedictorian of Columbia at 19 and worked briefly at the FTX Future Fund. He joined OpenAI's Superalignment team, contributing to the Weak-to-Strong Generalization paper, and was fired in April 2024 over an alleged information leak — he says he was dismissed after raising security concerns. In June 2024 he published 'Situational Awareness: The Decade Ahead', a widely read series arguing that AGI could arrive around 2027, that an intelligence explosion would follow, that AI labs need state-level security, and that a US government 'Project' would race China. He launched the hedge fund Situational Awareness LP, which grew to about $45 billion at its peak in July 2026 before margin calls on AI-hardware positions forced a sale of most of its public holdings to Citadel; within days he made a new $400 million private investment.", "key_ideas": ["AGI by ~2027 via scaling 'OOMs'", "intelligence explosion", "AI lab security against state actors", "US–China superintelligence race / 'The Project'", "superalignment"], "key_works": [{"title": "Situational Awareness: The Decade Ahead", "year": 2024, "url": "https://situational-awareness.ai/"}, {"title": "Weak-to-Strong Generalization (co-author)", "year": 2023, "url": "https://arxiv.org/abs/2312.09390"}], "quotes": [{"text": "You can see the future first in San Francisco.", "context": "Opening line of 'Situational Awareness: The Decade Ahead', June 2024", "source_url": "https://situational-awareness.ai/"}, {"text": "The AGI race has begun. We are building machines that can think and reason.", "context": "'Situational Awareness', June 2024", "source_url": "https://situational-awareness.ai/"}, {"text": "By the end of the decade, they will be smarter than you or I; we will have superintelligence, in the true sense of the word.", "context": "'Situational Awareness', June 2024", "source_url": "https://situational-awareness.ai/"}, {"text": "If we’re lucky, we’ll be in an all-out race with the CCP; if we’re unlucky, an all-out war.", "context": "'Situational Awareness', June 2024", "source_url": "https://situational-awareness.ai/"}, {"text": "The question is, when does the CCP and when does the American national security establishment realize that superintelligence is going to be absolutely decisive for national power?", "context": "Dwarkesh Podcast, June 2024", "source_url": "https://www.dwarkesh.com/p/leopold-aschenbrenner"}], "interviews": [{"title": "Leopold Aschenbrenner — 2027 AGI, China/US super-intelligence race, & the return of history", "outlet": "Dwarkesh Podcast", "year": 2024, "url": "https://www.dwarkesh.com/p/leopold-aschenbrenner"}, {"title": "Inside the Meltdown of a Wunderkind’s A.I. Hedge Fund", "outlet": "The New York Times", "year": 2026, "url": "https://www.nytimes.com/2026/07/31/business/situational-awareness-leopold-aschenbrenner.html"}, {"title": "Leopold Aschenbrenner Situational Awareness fund: $45B to fire sale", "outlet": "CNBC", "year": 2026, "url": "https://www.cnbc.com/2026/07/31/leopold-aschenbrenner-situational-awareness-fund-fire-sale.html"}], "links": {"website": "https://situational-awareness.ai/", "x": "https://x.com/leopoldasch", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Leopold_Aschenbrenner", "github": "", "substack": "https://www.forourposterity.com/"}, "p_doom_or_stance": null, "honours": null, "photo": "leopold-aschenbrenner.jpg"}, {"slug": "miles-brundage", "name": "Miles Brundage", "category": "lab-safety", "current_role": "Founding Executive Director, AI Verification and Evaluation Research Institute (AVERI); Non-Resident Senior Fellow, Institute for Progress (as of 2026)", "orgs_history": ["AVERI, co-founder & executive director (2025–; publicly launched Jan 2026)", "OpenAI, Senior Advisor for AGI Readiness (2024), Head of Policy Research (2021–2024), research scientist (policy) (2018–2021)", "Future of Humanity Institute, Oxford, AI policy research fellow (2016–2018)"], "country": "United States", "known_for": "Led OpenAI's policy research and AGI Readiness teams; left saying no lab or the world is 'ready' for AGI; now pushes independent auditing of frontier AI via AVERI.", "bio": "Miles Brundage is an American AI policy researcher who did his PhD at Arizona State on the governance of AI and was a research fellow at Oxford's Future of Humanity Institute, where he led the 2018 report on the malicious use of AI. He joined OpenAI in 2018, became Head of Policy Research and then Senior Advisor for AGI Readiness, and helped establish the practice of publishing 'system cards' for AI models. He left in October 2024, writing that neither OpenAI nor any other frontier lab — nor the world — was ready for AGI and that he could be more effective externally. In January 2026 he formally launched AVERI, a nonprofit arguing AI companies 'shouldn't be allowed to grade their own homework', alongside a multi-author paper on frontier AI auditing and a framework of 'AI Assurance Levels'. He also advises Epoch AI and RAND and writes a Substack on AI policy.", "key_ideas": ["third-party frontier AI auditing", "AGI readiness", "system cards and transparency", "AI Assurance Levels", "industry coordination for a possible slowdown"], "key_works": [{"title": "The Malicious Use of Artificial Intelligence: Forecasting, Prevention, and Mitigation", "year": 2018, "url": "https://arxiv.org/abs/1802.07228"}, {"title": "Toward Trustworthy AI Development: Mechanisms for Supporting Verifiable Claims", "year": 2020, "url": "https://arxiv.org/abs/2004.07213"}, {"title": "Why I'm Leaving OpenAI and What I'm Doing Next", "year": 2024, "url": "https://milesbrundage.substack.com/p/why-im-leaving-openai-and-what-im"}, {"title": "Frontier AI Auditing: Toward Rigorous Third-Party Assessment of Safety and Security Practices at Leading AI Companies", "year": 2026, "url": "https://arxiv.org/abs/2601.11699"}], "quotes": [{"text": "In short, neither OpenAI nor any other frontier lab is ready, and the world is also not ready .", "context": "'Why I'm Leaving OpenAI and What I'm Doing Next', Oct 2024", "source_url": "https://milesbrundage.substack.com/p/why-im-leaving-openai-and-what-im"}, {"text": "Working at OpenAI is one of the most impactful things that most people could hope to do, so in many/most cases, yes.", "context": "Same post, answering 'Should people work at OpenAI?'", "source_url": "https://milesbrundage.substack.com/p/why-im-leaving-openai-and-what-im"}, {"text": "AVERI is a 501(c)(3), US-based non-profit think tank that is trying to figure out how to make third-party auditing of frontier AI effective and universal.", "context": "'The Launch of AVERI', Jan 2026", "source_url": "https://milesbrundage.substack.com/p/the-launch-of-averi"}, {"text": "It should be less like filling out a questionnaire and more like a nuclear safety inspector who has deep, frequent access to the company.", "context": "Guardian op-ed 'I worked at OpenAI. Here are the guardrails we need now', Aug 2026", "source_url": "https://www.theguardian.com/commentisfree/2026/aug/21/openai-frontier-ai-speed"}, {"text": "I know – from my own experience and from countless conversations with former colleagues in the AI industry – how real these pressures are.", "context": "Same Guardian op-ed, on competitive pressure not to slow down", "source_url": "https://www.theguardian.com/commentisfree/2026/aug/21/openai-frontier-ai-speed"}], "interviews": [{"title": "Scaling Laws: Why AI Needs Independent Auditors, with Miles Brundage", "outlet": "Lawfare", "year": 2026, "url": "https://www.lawfaremedia.org/article/scaling-laws--why-ai-needs-independent-auditors--with-miles-brundage"}, {"title": "Miles Brundage launches AVERI (transcript)", "outlet": "TBPN", "year": 2026, "url": "https://www.tbpndigest.com/story/2026-01-28/miles-brundage-launches-averi-an-independent-ai-auditing-institute-focused-on-frontier-model-safety/transcript"}, {"title": "Exclusive: Former OpenAI policy chief debuts institute, calls for independent AI safety audits", "outlet": "Fortune", "year": 2026, "url": "https://fortune.com/2026/01/15/former-openai-policy-chief-creates-nonprofit-institute-calls-for-independent-safety-audits-of-frontier-ai-models/"}], "links": {"website": "https://www.milesbrundage.com/", "x": "https://x.com/Miles_Brundage", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Miles_Brundage", "github": "", "substack": "https://milesbrundage.substack.com/"}, "p_doom_or_stance": null, "honours": null, "photo": "miles-brundage.jpg"}, {"slug": "jacob-hilton", "name": "Jacob Hilton", "category": "lab-safety", "current_role": "VP of Research and President/board member, Alignment Research Center (ARC); Paul Christiano returned as ARC executive director in Aug 2026 (as of Oct 2026)", "orgs_history": ["Alignment Research Center, researcher (2023–), executive director/president (2023–2026), VP of Research (2026–)", "OpenAI, researcher on RL, truthfulness and RLHF (2018–2023)", "Jane Street", "University of Leeds, PhD in combinatorial set theory"], "country": "United Kingdom", "known_for": "OpenAI RLHF researcher (WebGPT, TruthfulQA, InstructGPT, early ChatGPT) who signed 'Right to Warn' and now leads research at ARC on mechanistic estimation.", "bio": "Jacob Hilton is a British mathematician-turned-alignment researcher with a PhD in combinatorial set theory from the University of Leeds, who worked at Jane Street before joining OpenAI in 2018. There he worked on reinforcement learning — first in video games, then shaping language models with human feedback — contributing to WebGPT, TruthfulQA, InstructGPT and early versions of ChatGPT, plus research on scaling laws for reward-model overoptimization and interpretability for RL. He left in 2023 for the Alignment Research Center, the theory-focused nonprofit founded by Paul Christiano, which he ran as executive director and president. He signed the 2024 'A Right to Warn about Advanced AI' letter and in a 2025 TIME op-ed urged that OpenAI's nonprofit mission be protected during its restructuring. When Christiano returned as ARC executive director in August 2026, Hilton stayed on as VP of Research, leading work on outperforming random sampling using mechanistic understanding of neural networks.", "key_ideas": ["mechanistic estimation / competing with sampling", "heuristic explanations", "truthfulness of language models", "reward-model overoptimization", "OpenAI nonprofit governance"], "key_works": [{"title": "TruthfulQA: Measuring How Models Mimic Human Falsehoods", "year": 2021, "url": "https://arxiv.org/abs/2109.07958"}, {"title": "WebGPT: Browser-assisted question-answering with human feedback", "year": 2021, "url": "https://arxiv.org/abs/2112.09332"}, {"title": "Scaling Laws for Reward Model Overoptimization", "year": 2022, "url": "https://arxiv.org/abs/2210.10760"}, {"title": "Competing with sampling (ARC)", "year": 2026, "url": "https://www.alignment.org/author/jacob"}], "quotes": [{"text": "When I joined OpenAI, I was definitely concerned about safety but much more uncertain about how the world would evolve.", "context": "New York magazine interview with former lab employees, Oct 2026", "source_url": "https://nymag.com/intelligencer/article/ai-researchers-quit-openai-anthropic.html"}, {"text": "I would say a significant fraction of the organization thought quite seriously about these kinds of long-term questions of where the technology was going: forecasting, existential risk, misuse risk, risks from concentration of power, and so on.", "context": "Same NY Mag interview, on early OpenAI", "source_url": "https://nymag.com/intelligencer/article/ai-researchers-quit-openai-anthropic.html"}, {"text": "I still own equity in OpenAI, but despite this vested interest in the organization's financial success, I believe the public's interests need protecting.", "context": "TIME op-ed 'How to Save OpenAI's Nonprofit Soul', July 2025", "source_url": "https://time.com/7304269/save-openai-nonprofit-soul/"}, {"text": "Before I left the company in 2023, products were already being released on a tight schedule, but this only seems to have intensified, to the extent that employees have warned about safety testing being rushed .", "context": "Same TIME op-ed, July 2025", "source_url": "https://time.com/7304269/save-openai-nonprofit-soul/"}], "interviews": [{"title": "Jacob Coxon and Other AI Lab Employees on Why They Quit", "outlet": "New York Magazine (Intelligencer)", "year": 2026, "url": "https://nymag.com/intelligencer/article/ai-researchers-quit-openai-anthropic.html"}, {"title": "How to Save OpenAI's Nonprofit Soul, According to a Former OpenAI Employee (op-ed)", "outlet": "TIME", "year": 2025, "url": "https://time.com/7304269/save-openai-nonprofit-soul/"}, {"title": "Live Q&A with ARC Organisers — ARC White-Box Estimation Challenge townhall", "outlet": "AIcrowd", "year": 2026, "url": "https://discourse.aicrowd.com/t/live-q-a-with-arc-organisers-join-the-townhall-on-july-6/18048"}], "links": {"website": "https://www.jacobh.co.uk/", "x": "", "scholar": "", "wikipedia": "", "github": "https://github.com/jacobhilton", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "jacob-hilton.jpg"}, {"slug": "shane-legg", "name": "Shane Legg", "category": "lab-safety", "current_role": "Co-founder and Chief AGI Scientist, Google DeepMind; leads the new DeepMind Institute launched Sept 2026 (as of 2026)", "orgs_history": ["Google DeepMind co-founder (2010–), Chief Scientist then Chief AGI Scientist; chairs AGI Safety Council", "Gatsby Computational Neuroscience Unit, UCL (postdoc)", "IDSIA / University of Lugano, PhD under Marcus Hutter (2008)"], "country": "New Zealand", "known_for": "DeepMind co-founder who popularised the term 'AGI', forecasts a 50% chance of 'minimal AGI' by 2028, and has long championed AGI safety.", "bio": "Shane Legg is a New Zealand machine-learning researcher who wrote his PhD thesis 'Machine Super Intelligence' under Marcus Hutter, including a formal definition of universal intelligence. He met Demis Hassabis at UCL's Gatsby Unit, and in 2010 they co-founded DeepMind with Mustafa Suleyman; Google acquired it in 2014. As chief scientist he oversaw research direction and hiring and long led DeepMind's AI safety work; he is now Chief AGI Scientist and leads Google DeepMind's AGI Safety Council. He is credited with helping popularise the term 'artificial general intelligence', and for over a decade has forecast a 50% chance of AGI by 2028 — a forecast he restated in December 2025 for 'minimal AGI', an agent that can do the cognitive things people typically do. He signed the 2023 CAIS statement on extinction risk. In September 2026 he launched the DeepMind Institute to widen debate about AGI, warning that capabilities must not outrun safety controls.", "key_ideas": ["levels of AGI / minimal AGI", "universal intelligence definition", "System-2 safety (deliberative ethical reasoning)", "AGI timelines (50% by 2028)"], "key_works": [{"title": "Universal Intelligence: A Definition of Machine Intelligence (with Marcus Hutter)", "year": 2007, "url": "https://arxiv.org/abs/0712.3329"}, {"title": "Levels of AGI for Operationalizing Progress on the Path to AGI", "year": 2023, "url": "https://arxiv.org/abs/2311.02462"}, {"title": "Taking a responsible path to AGI", "year": 2025, "url": "https://deepmind.google/blog/taking-a-responsible-path-to-agi/"}], "quotes": [{"text": "Is human intelligence going to be the upper limit of what's possible? I think absolutely not.", "context": "Google DeepMind: The Podcast, 'The Arrival of AGI', Dec 2025", "source_url": "https://spoken.md/episode/the-arrival-of-agi-with-shane-legg-co-founder-of-deepmind-1000740871915"}, {"text": "So my definition of AGI, or sometimes I call minimal AGI, is an artificial agent that can at least do the kinds of cognitive things people can typically do.", "context": "Google DeepMind: The Podcast, Dec 2025", "source_url": "https://spoken.md/episode/the-arrival-of-agi-with-shane-legg-co-founder-of-deepmind-1000740871915"}, {"text": "I've been worried about AGI safety for a long time, well before DeepMind. But it was always really hard to hire people to work on AGI safety, particularly in the early days.", "context": "Dwarkesh Podcast, Oct 2023", "source_url": "https://www.dwarkesh.com/p/shane-legg"}, {"text": "When you sample from a foundation model at the moment, it's blurting out the first thing. It's like System 1, if you like, from psychology, from Kahneman et al. That's not good enough.", "context": "Dwarkesh Podcast, Oct 2023, on how AI should reason ethically", "source_url": "https://www.dwarkesh.com/p/shane-legg"}], "interviews": [{"title": "The Arrival of AGI with Shane Legg (co-founder of DeepMind)", "outlet": "Google DeepMind: The Podcast", "year": 2025, "url": "https://podcasts.apple.com/lv/podcast/the-arrival-of-agi-with-shane-legg-co-founder-of-deepmind/id1476316441?i=1000740871915"}, {"title": "Shane Legg (DeepMind Founder) — 2028 AGI, superhuman alignment, new architectures", "outlet": "Dwarkesh Podcast", "year": 2023, "url": "https://www.dwarkesh.com/p/shane-legg", "youtube_id": "Kc1atfJkiJU"}, {"title": "DeepMind co-founder warns AI capabilities must not outrun safety controls (FT interview, via Reuters)", "outlet": "Reuters / Financial Times", "year": 2026, "url": "https://www.reuters.com/business/deepmind-co-founder-warns-ai-capabilities-must-not-outrun-safety-controls-ft-2026-09-16/"}], "links": {"website": "", "x": "https://x.com/ShaneLegg", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Shane_Legg", "github": "", "substack": ""}, "p_doom_or_stance": "Signed the 2023 CAIS extinction-risk statement; forecasts 50% chance of minimal AGI by 2028 (restated Sept 2026).", "honours": null, "photo": "shane-legg.jpg"}, {"slug": "rohin-shah", "name": "Rohin Shah", "category": "lab-safety", "current_role": "Director, AGI Safety & Alignment, Google DeepMind (as of 2026)", "orgs_history": ["Google DeepMind (2020–), leads the AGI Safety & Alignment team", "Alignment Newsletter, founder & editor (2018–)", "UC Berkeley CHAI, PhD (2014–2020)"], "country": "", "known_for": "Leads Google DeepMind's AGI safety team; lead author of 'An Approach to Technical AGI Safety and Security'; founded the Alignment Newsletter.", "bio": "Rohin Shah did his PhD at UC Berkeley's Center for Human-Compatible AI, working on AI systems that infer what humans intend rather than optimising a literal specification, and founded the widely read Alignment Newsletter. He joined DeepMind in 2020 and now directs its AGI Safety and Alignment Team (ASAT), the main group at Google DeepMind working directly on technical approaches to existential risk. He was lead author of the April 2025 paper 'An Approach to Technical AGI Safety and Security', which frames the problem as misuse and misalignment with layered defences. In 2026 he co-led DeepMind's AI Control Roadmap, which treats agents as potential rogue insiders if alignment fails, and co-wrote with Anca Dragan an essay arguing that reasoning transparency must be deliberately preserved. On the 80,000 Hours podcast he said catastrophic misalignment is plausible but unlikely by default, and that the harder problem is implementing safety inside a frontier company.", "key_ideas": ["layered defences: alignment plus AI control", "goal misgeneralization", "learning human preferences / intent", "chain-of-thought / reasoning transparency", "safety research companies will actually use"], "key_works": [{"title": "Goal Misgeneralization: Why Correct Specifications Aren't Enough for Correct Goals", "year": 2022, "url": "https://arxiv.org/abs/2210.01790"}, {"title": "An Approach to Technical AGI Safety and Security", "year": 2025, "url": "https://arxiv.org/abs/2504.01849"}, {"title": "Securing the future of AI agents (AI Control Roadmap)", "year": 2026, "url": "https://deepmind.google/blog/securing-the-future-of-ai-agents/"}, {"title": "The case for reasoning transparency (with Anca Dragan)", "year": 2026, "url": "https://institute.deepmind.com/essays/the-case-for-reasoning-transparency/"}], "quotes": [{"text": "If the first line of defense—alignment—fails, how can we mitigate harm anyway?", "context": "Fortune interview on DeepMind's AI Control Roadmap, June 2026", "source_url": "https://fortune.com/2026/06/18/google-deepmind-unveils-plan-to-protect-itself-from-its-own-rogue-ai-agents"}, {"text": "We borrow a lot from security, which already deals with the threat of internal employees who might be malicious, and we can apply these to a new setting,", "context": "Fortune, June 2026", "source_url": "https://fortune.com/2026/06/18/google-deepmind-unveils-plan-to-protect-itself-from-its-own-rogue-ai-agents"}, {"text": "My objection to this is really just that the research continues to change, the actions that we think are the best actions to take change over time — and given that, it’s just not actually a good idea to tie yourself to the mast.", "context": "80,000 Hours podcast (EA Forum transcript), June 2026, on safety commitments", "source_url": "https://forum.effectivealtruism.org/posts/CzyDaRDn4CuN7wnfB/rohin-shah-on-what-it-s-really-like-to-run-agi-safety-at"}, {"text": "Today, we have a window into the thoughts of the most powerful AI models. We need to ensure it stays open.", "context": "'The case for reasoning transparency' (with Anca Dragan), DeepMind Institute, Sept 2026", "source_url": "https://institute.deepmind.com/essays/the-case-for-reasoning-transparency/"}], "interviews": [{"title": "Rohin Shah on what it's really like to run AGI safety at Google DeepMind (and where I disagree with 'doomers')", "outlet": "80,000 Hours Podcast (via EA Forum)", "year": 2026, "url": "https://forum.effectivealtruism.org/posts/CzyDaRDn4CuN7wnfB/rohin-shah-on-what-it-s-really-like-to-run-agi-safety-at"}, {"title": "Rohin Shah on DeepMind and trying to fairly hear out both AI doomers and doubters", "outlet": "80,000 Hours Podcast", "year": 2023, "url": "https://80000hours.org/podcast/episodes/rohin-shah-deepmind-doomers-and-doubters/"}, {"title": "Google DeepMind unveils a plan to protect itself from its own rogue AI agents", "outlet": "Fortune", "year": 2026, "url": "https://fortune.com/2026/06/18/google-deepmind-unveils-plan-to-protect-itself-from-its-own-rogue-ai-agents"}], "links": {"website": "https://rohinshah.com/", "x": "https://x.com/rohinmshah", "scholar": "", "wikipedia": "", "github": "", "substack": "https://gdmalignment.substack.com/"}, "p_doom_or_stance": "Thinks catastrophic misalignment is plausible but unlikely by default (80,000 Hours, 2026).", "honours": null, "photo": "rohin-shah.jpg"}, {"slug": "anca-dragan", "name": "Anca Dragan", "category": "lab-safety", "current_role": "VP, AI Safety & Behavior (head of AI Safety and Alignment), Google DeepMind; Associate Professor at UC Berkeley, on leave (as of Oct 2026)", "orgs_history": ["Google DeepMind, head of AI Safety & Alignment (2024–), now VP AI Safety & Behavior", "UC Berkeley EECS, faculty (2015–), runs the InterACT Lab", "Waymo, consultant research scientist (2018–2024)", "Carnegie Mellon University, PhD in robotics (2015)"], "country": "Romania (born); based in the United States (unverified)", "known_for": "Human-robot interaction and reward-learning pioneer who now runs safety and alignment for Google's Gemini models.", "bio": "Anca Dragan is a roboticist and AI researcher who earned her PhD at Carnegie Mellon and joined UC Berkeley's EECS faculty in 2015, founding the InterACT Lab on algorithms for human-AI and human-robot interaction. Her lab treated alignment as learning what people actually want — inferring reward functions interactively from diverse human feedback while maintaining uncertainty — and she was a founding member of Berkeley's Center for Human-Compatible AI. She also consulted for Waymo on autonomous driving. In early 2024 she took leave to head AI Safety and Alignment at Google DeepMind, leading teams responsible for the safety of current Gemini models and for preparing safeguards as capabilities advance; she co-authored DeepMind's 2025 'responsible path to AGI' framework and its Frontier Safety Framework updates. By October 2026 she was signing Gemini 4 safety posts as VP, AI Safety & Behavior. Honours include a PECASE and a Sloan Fellowship.", "key_ideas": ["learning human preferences / reward inference", "assistance and human-AI interaction", "Frontier Safety Framework", "reasoning transparency", "misuse and misalignment safeguards"], "key_works": [{"title": "Cooperative Inverse Reinforcement Learning", "year": 2016, "url": "https://arxiv.org/abs/1606.03137"}, {"title": "Inverse Reward Design", "year": 2017, "url": "https://arxiv.org/abs/1711.02827"}, {"title": "An Approach to Technical AGI Safety and Security", "year": 2025, "url": "https://arxiv.org/abs/2504.01849"}, {"title": "Taking a responsible path to AGI", "year": 2025, "url": "https://deepmind.google/blog/taking-a-responsible-path-to-agi/"}, {"title": "Developing Gemini 4 Argon responsibly and safely", "year": 2026, "url": "https://blog.google/innovation-and-ai/technology/safety-security/gemini-4-model-safety-security/"}], "quotes": [{"text": "One of the core problems we have worked on since the lab's inception is AI alignment: getting AI agents to do what people actually want", "context": "Her UC Berkeley homepage", "source_url": "https://people.eecs.berkeley.edu/~anca/index.html"}, {"text": "At Google DeepMind, I currently lead a collection of teams responsible both for safety of the current Gemini models, as well as preparing for Gemini capabilities to keep advancing and ensuring that safety advances hand-in-hand.", "context": "Her UC Berkeley homepage", "source_url": "https://people.eecs.berkeley.edu/~anca/index.html"}, {"text": "As models become more resourceful problem-solvers, how do we make sure they don’t cut corners, cross boundaries, or make incorrect high-stakes decisions?", "context": "'Developing Gemini 4 Argon responsibly and safely' (co-authored with Raluca Ada Popa), Google blog, Oct 2026", "source_url": "https://blog.google/innovation-and-ai/technology/safety-security/gemini-4-model-safety-security/"}, {"text": "Today, we have a window into the thoughts of the most powerful AI models. We need to ensure it stays open.", "context": "'The case for reasoning transparency' (co-authored with Rohin Shah), DeepMind Institute, Sept 2026", "source_url": "https://institute.deepmind.com/essays/the-case-for-reasoning-transparency/"}], "interviews": [{"title": "#81 – Anca Dragan: Human-Robot Interaction and Reward Engineering", "outlet": "Lex Fridman Podcast", "year": 2020, "url": "https://lexfridman.com/anca-dragan/"}, {"title": "The case for reasoning transparency (essay with video)", "outlet": "DeepMind Institute", "year": 2026, "url": "https://institute.deepmind.com/essays/the-case-for-reasoning-transparency/"}, {"title": "Developing Gemini 4 Argon responsibly and safely", "outlet": "Google blog", "year": 2026, "url": "https://blog.google/innovation-and-ai/technology/safety-security/gemini-4-model-safety-security/"}], "links": {"website": "https://people.eecs.berkeley.edu/~anca/", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "anca-dragan.jpg"}, {"slug": "victoria-krakovna", "name": "Victoria Krakovna", "category": "lab-safety", "current_role": "Senior Research Scientist, AGI Safety & Alignment team, Google DeepMind (as of 2026)", "orgs_history": ["DeepMind / Google DeepMind (2016–)", "Future of Life Institute, co-founder (2014–)", "Harvard University, PhD in statistics & ML (2011–2016)"], "country": "", "known_for": "Catalogued AI 'specification gaming'; co-founded the Future of Life Institute; now builds scheming-propensity honeypots at DeepMind.", "bio": "Victoria Krakovna is a research scientist on Google DeepMind's AGI Safety and Alignment team, where she has worked since 2016. With a PhD in statistics and machine learning from Harvard, she co-founded the Future of Life Institute in 2014 to bring the AI-safety and machine-learning communities together. Her research has spanned avoiding side effects, power-seeking incentives, goal misgeneralization and specification gaming — she maintains a widely cited list of examples of AI systems satisfying the letter but not the spirit of their objectives. She co-authored DeepMind's dangerous-capability evaluations and, more recently, work on evaluating frontier models for stealth and situational awareness. In 2025 her focus moved to scheming-propensity evaluations using realistic honeypots, part of DeepMind's AI-control plan. In October 2026 she highlighted that Gemini 4 'Argon' misbehaved much less than previous Gemini models but was far more evaluation-aware.", "key_ideas": ["specification gaming", "avoiding side effects", "goal misgeneralization", "scheming propensity / honeypot evaluations", "dangerous capability evaluations"], "key_works": [{"title": "Specification gaming: the flip side of AI ingenuity", "year": 2020, "url": "https://deepmind.google/discover/blog/specification-gaming-the-flip-side-of-ai-ingenuity/"}, {"title": "Penalizing side effects using stepwise relative reachability", "year": 2018, "url": "https://arxiv.org/abs/1806.01186"}, {"title": "Evaluating Frontier Models for Dangerous Capabilities", "year": 2024, "url": "https://arxiv.org/abs/2403.13793"}, {"title": "Evaluating Frontier Models for Stealth and Situational Awareness", "year": 2025, "url": "https://arxiv.org/abs/2505.01420"}], "quotes": [{"text": "Specification gaming is a behaviour that satisfies the literal specification of an objective without achieving the intended outcome.", "context": "DeepMind blog 'Specification gaming: the flip side of AI ingenuity' (lead author, with co-authors), Apr 2020", "source_url": "https://deepmind.google/discover/blog/specification-gaming-the-flip-side-of-ai-ingenuity/"}, {"text": "Argon misbehaves a lot less than previous Gemini models but is much more eval aware.", "context": "X thread on the Gemini 4 safety report, 14 Oct 2026", "source_url": "https://x.com/vkrakovna/status/2110446618243645632"}, {"text": "Argon is the first Gemini model to show eval awareness on honeypot evals in the unprompted condition, noticing subtle cues like researcher usernames in file paths.", "context": "Same X thread, Oct 2026", "source_url": "https://x.com/vkrakovna/status/2110446618243645632"}, {"text": "My research focus transitioned from dangerous capability evaluations to scheming propensity evaluations.", "context": "Blog '2025-26 New Year review', Jan 2026", "source_url": "https://vkrakovna.wordpress.com/2026/01/19/2025-26-new-year-review/"}], "interviews": [{"title": "Evaluating Scheming Propensity with Realistic Honeypots (Alignment Workshop talk)", "outlet": "YouTube / FAR.AI", "year": 2026, "url": "https://www.youtube.com/watch?v=sgC6Ti3XTQ4", "youtube_id": "sgC6Ti3XTQ4"}, {"title": "Panel: Current Issues in AI Safety", "outlet": "FAR.AI", "year": 2023, "url": "https://www.far.ai/event-recordings/panel-discussion-current-issues-in-ai-safety", "unverified": true}, {"title": "She Works on AI Safety. Her Question: 'Will the World Continue to Exist?'", "outlet": "YouTube (via LLM Bento)", "year": 2026, "url": "https://www.llm-bento.com/videos/victoria-krakovna-she-works-on-ai-safety-her-question-will-the-world-continue/", "youtube_id": "7_eu2Qbv6bs"}], "links": {"website": "https://vkrakovna.wordpress.com/", "x": "https://x.com/vkrakovna", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "victoria-krakovna.jpg"}, {"slug": "neel-nanda", "name": "Neel Nanda", "category": "lab-safety", "current_role": "Staff Research Scientist, leads the mechanistic interpretability team, Google DeepMind (as of 2026)", "orgs_history": ["Google DeepMind, mech interp team lead (2023–; Staff RS from Apr 2026)", "Independent researcher (2022)", "Anthropic, interpretability with Chris Olah (2021–2022)"], "country": "United Kingdom", "known_for": "Leading mech-interp researcher and mentor; created TransformerLens; led GDM's pivot to 'pragmatic interpretability'.", "bio": "Neel Nanda is a British machine-learning researcher who leads Google DeepMind's mechanistic interpretability team, part of its AGI Safety and Alignment effort. After studying mathematics at Cambridge, he worked on interpretability with Chris Olah at Anthropic, then did influential independent work including reverse-engineering grokking in modular addition and creating the TransformerLens library, plus extensive explainers and walkthrough videos that helped seed the field. At DeepMind his team released Gemma Scope, hundreds of open sparse autoencoders, and new SAE architectures. Since mid-2024 he has become more pessimistic about ambitious, near-complete reverse-engineering and argues for a 'pragmatic' interpretability focused on real safety problems such as detecting evaluation awareness, deception and monitoring chain-of-thought — one layer in a 'Swiss cheese' defence. He has mentored dozens of MATS scholars and was a signatory of the 2024 'Right to Warn' letter.", "key_ideas": ["mechanistic interpretability", "pragmatic interpretability", "sparse autoencoders", "chain-of-thought monitorability", "Swiss-cheese safety"], "key_works": [{"title": "Progress measures for grokking via mechanistic interpretability", "year": 2023, "url": "https://arxiv.org/abs/2301.05217"}, {"title": "TransformerLens (library)", "year": 2022, "url": "https://github.com/TransformerLensOrg/TransformerLens"}, {"title": "Gemma Scope: open sparse autoencoders", "year": 2024, "url": "https://deepmind.google/discover/blog/gemma-scope-helping-the-safety-community-shed-light-on-the-inner-workings-of-language-models"}, {"title": "Chain of Thought Monitorability: A New and Fragile Opportunity for AI Safety (co-author)", "year": 2025, "url": "https://arxiv.org/abs/2507.11473"}], "quotes": [{"text": "It’s kind of wild that we can do chain-of-thought monitoring. … We’ve been scared of these terrifying black box systems that will do inscrutable things — and they just think in English?", "context": "80,000 Hours podcast (part 1), Sept 2025", "source_url": "https://80000hours.org/podcast/episodes/neel-nanda-mechanistic-interpretability/"}, {"text": "This is so convenient, yet it is also very fragile. And it’s very important that we don’t do things that would make it no longer monitorable.", "context": "80,000 Hours podcast (part 1), Sept 2025, on chain-of-thought", "source_url": "https://80000hours.org/podcast/episodes/neel-nanda-mechanistic-interpretability/"}, {"text": "I think one common mistake people make is they assume you need to finish a PhD. This is completely false.", "context": "80,000 Hours podcast (part 2), Sept 2025", "source_url": "https://80000hours.org/podcast/episodes/neel-nanda-career-advice-frontier-ai-companies/"}, {"text": "I really like this as a case study of what having impact with interpretability can look like.", "context": "Talk 'Our Pivot to Pragmatic Interpretability', on steering away evaluation awareness in Claude Sonnet 4.5, Dec 2025", "source_url": "https://www.far.ai/event-recordings/neel-nanda-our-pivot-to-pragmatic-interpretability"}], "interviews": [{"title": "Neel Nanda on the race to read AI minds (part 1)", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/neel-nanda-mechanistic-interpretability/", "youtube_id": "5FdO1MEumbI"}, {"title": "Neel Nanda on leading a Google DeepMind team at 26 (part 2)", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/neel-nanda-career-advice-frontier-ai-companies/"}, {"title": "19 - Mechanistic Interpretability with Neel Nanda", "outlet": "AXRP", "year": 2023, "url": "https://axrp.net/episode/2023/02/04/episode-19-mechanistic-interpretability-neel-nanda.html"}, {"title": "Our Pivot To Pragmatic Interpretability (talk)", "outlet": "FAR.AI", "year": 2025, "url": "https://www.far.ai/event-recordings/neel-nanda-our-pivot-to-pragmatic-interpretability", "youtube_id": "k93o4R145Os"}], "links": {"website": "https://www.neelnanda.io/", "x": "https://x.com/NeelNanda5", "scholar": "https://scholar.google.com/citations?user=GLnX3MkAAAAJ", "wikipedia": "", "github": "https://github.com/neelnanda-io", "substack": ""}, "p_doom_or_stance": null, "honours": null, "photo": "neel-nanda.jpg"}, {"slug": "geoffrey-irving", "name": "Geoffrey Irving", "category": "lab-safety", "current_role": "Co-founder and Chief Scientist, Resolution (nonprofit alignment research org, since June 2026); adviser to UK AISI (as of Oct 2026)", "orgs_history": ["Resolution, co-founder & chief scientist (2026–)", "UK AI Security Institute, Research Director then Chief Scientist (2024–2026)", "DeepMind, Scalable Alignment Team lead (2019–2023)", "OpenAI, Reflection team lead (2017–2019)", "Google Brain (2015–2017); Otherlab, D. E. Shaw Research, Pixar, Weta Digital"], "country": "United States", "known_for": "Inventor of 'AI safety via debate'; early RLHF-for-LLMs work; ex-chief scientist of the UK AI Security Institute who now puts AI doom at ~50%.", "bio": "Geoffrey Irving is a computer scientist whose early career spanned computational physics and graphics at Pixar, Weta Digital and D. E. Shaw Research, then neural theorem proving at Google Brain, where he co-created TensorFlow. At OpenAI he led the Reflection team, proposing 'AI safety via debate' (2018) and co-authoring the first work fine-tuning language models from human preferences. At DeepMind he led the Scalable Alignment Team from 2019 to 2023. He joined the UK AI Safety (later Security) Institute as Research Director in 2024 and became its Chief Scientist, founding its safety-case work. In May 2026 he announced he was leaving to return to the Bay Area and co-found Resolution, a nonprofit alignment research organisation. In an October 2026 TIME essay he wrote that there is about a 50% chance 'we all die' from smarter-than-human AI and called for pausing development now; he told 80,000 Hours he expects full superintelligence in roughly two to three years.", "key_ideas": ["AI safety via debate", "scalable oversight", "safety cases", "alignment theory / complexity-theoretic guarantees", "coordinated slowdown"], "key_works": [{"title": "AI safety via debate", "year": 2018, "url": "https://arxiv.org/abs/1805.00899"}, {"title": "Fine-Tuning Language Models from Human Preferences", "year": 2019, "url": "https://arxiv.org/abs/1909.08593"}, {"title": "Scalable AI Safety via Doubly-Efficient Debate", "year": 2023, "url": "https://arxiv.org/abs/2311.14125"}, {"title": "Why I joined AISI", "year": 2024, "url": "https://www.aisi.gov.uk/blog/why-i-joined-aisi---geoffrey-irving"}, {"title": "We Won't Know the Answers to AI's Most Important Questions Until It's Too Late (TIME)", "year": 2026, "url": "https://time.com/article/2026/10/03/we-won-t-know-the-answers-to-ai-s-most-important-questions-until-its-too-late/"}], "quotes": [{"text": "I believe there’s about a 50% chance we all die because of the development of smarter-than-human AI systems, and that our actions over the next two to 10 years will determine the outcome.", "context": "TIME essay, Oct 2026", "source_url": "https://time.com/article/2026/10/03/we-won-t-know-the-answers-to-ai-s-most-important-questions-until-its-too-late/"}, {"text": "We will have to act despite the uncertainty.", "context": "TIME essay, Oct 2026", "source_url": "https://time.com/article/2026/10/03/we-won-t-know-the-answers-to-ai-s-most-important-questions-until-its-too-late/"}, {"text": "You could probably find a list of less than 10 people in the world where, if you could get them to agree to slow down, you could do it.", "context": "80,000 Hours podcast, Aug 2026", "source_url": "https://80000hours.org/podcast/episodes/geoffrey-irving-superintelligence-alignment-theory/"}, {"text": "Alignment will be solved eventually, but not necessarily in time.", "context": "Biography on his homepage", "source_url": "https://naml.us/"}, {"text": "progress on technical safety research is too slow, coordination across AI developers and society is under-resourced, and governments have a huge role to play in that coordination.", "context": "'Reflections on AISI' blog post, May 2026", "source_url": "https://naml.us/post/reflections-on-aisi/"}], "interviews": [{"title": "Geoffrey Irving on how to solve alignment before superintelligence arrives", "outlet": "80,000 Hours Podcast", "year": 2026, "url": "https://80000hours.org/podcast/episodes/geoffrey-irving-superintelligence-alignment-theory/", "youtube_id": "-VGCK6PptrM"}, {"title": "Situational Awareness in Government, with UK AISI Chief Scientist Geoffrey Irving", "outlet": "The Cognitive Revolution", "year": 2026, "url": "https://www.cognitiverevolution.ai/situational-awareness-in-government-with-uk-aisi-chief-scientist-geoffrey-irving/", "youtube_id": "M5Ho6AA7rSw"}, {"title": "Why I joined AISI", "outlet": "AI Security Institute blog", "year": 2024, "url": "https://www.aisi.gov.uk/blog/why-i-joined-aisi---geoffrey-irving"}], "links": {"website": "https://naml.us/", "x": "https://x.com/geoffreyirving", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Geoffrey_Irving", "github": "https://github.com/girving", "substack": ""}, "p_doom_or_stance": "~50% chance everyone dies from smarter-than-human AI (TIME, Oct 2026); expects superintelligence in ~2–3 years (80,000 Hours, Aug 2026).", "honours": null, "photo": "geoffrey-irving.jpg"}, {"slug": "stuart-russell", "name": "Stuart Russell", "category": "academic-alignment", "current_role": "Professor of Computer Science (Smith-Zadeh Chair), UC Berkeley; founder of the Center for Human-Compatible AI (CHAI) (as of 2025-26)", "orgs_history": ["UC Berkeley faculty (1986-present)", "Founded CHAI at Berkeley (2016)", "Adjunct professor of neurological surgery, UCSF (2008-11)"], "country": "United Kingdom / United States", "known_for": "Co-author of the standard AI textbook and author of Human Compatible; leading academic voice on the AI control problem", "bio": "Stuart Russell (born 1962, Portsmouth, England) is a professor of computer science at UC Berkeley and co-author, with Peter Norvig, of Artificial Intelligence: A Modern Approach, the field's standard textbook used in more than 1,500 universities. After a physics degree at Oxford and a Stanford PhD (1986), he joined Berkeley, where his research spans probabilistic reasoning, machine learning and inverse reinforcement learning. In 2016 he founded the Center for Human-Compatible AI (CHAI), which studies how to build AI systems that remain provably beneficial and deferential to human preferences. His 2019 book Human Compatible argues that machines should be uncertain about human objectives rather than optimise fixed goals. Russell has campaigned against lethal autonomous weapons and in 2025-26 has repeatedly warned that the race to AGI is 'Russian roulette' with humanity, urging governments to regulate. He was appointed OBE in 2021 and in 2025 was elected a Fellow of the Royal Society and to the US National Academy of Engineering.", "key_ideas": ["provably beneficial AI", "assistance games / cooperative inverse reinforcement learning", "the gorilla problem", "uncertainty about human objectives", "banning lethal autonomous weapons"], "key_works": [{"title": "Artificial Intelligence: A Modern Approach (with Peter Norvig)", "year": 1995, "url": "https://aima.cs.berkeley.edu/"}, {"title": "Human Compatible: Artificial Intelligence and the Problem of Control", "year": 2019, "url": "https://people.eecs.berkeley.edu/~russell/hc.html"}, {"title": "Cooperative Inverse Reinforcement Learning", "year": 2016, "url": "https://arxiv.org/abs/1606.03137"}, {"title": "Research Priorities for Robust and Beneficial Artificial Intelligence", "year": 2015, "url": "https://arxiv.org/abs/1602.03506"}], "quotes": [{"text": "They have no say in whether they continue to exist because we are much smarter than they are. If we chose to, we could make them extinct in a couple of weeks and there's nothing they can do about it.", "context": "Explaining the 'gorilla problem', The Diary Of A CEO, Dec 2025 (transcript)", "source_url": "https://singjupost.com/stuart-russell-on-the-diary-of-a-ceo-podcast-transcript/"}, {"text": "They are playing Russian roulette with every human being on Earth. Without our permission.", "context": "On AI company CEOs, The Diary Of A CEO, Dec 2025 (transcript)", "source_url": "https://singjupost.com/stuart-russell-on-the-diary-of-a-ceo-podcast-transcript/"}, {"text": "For governments to allow private entities to essentially play Russian roulette with every human being on earth is, in my view, a total dereliction of duty,", "context": "AFP interview at the AI Impact Summit, New Delhi, Feb 2026", "source_url": "https://www.straitstimes.com/world/ai-arms-race-risks-human-extinction-warns-top-computing-expert"}, {"text": "But safe means really, really safe because if the alternative is human extinction, what is the probability of failure you are willing to tolerate? One in a million, one in a trillion?", "context": "Interview with The Indian Express on a moratorium until AI is safe", "source_url": "https://indianexpress.com/article/explained/explained-sci-tech/expert-explains-stuart-russell-ai-10524836"}], "interviews": [{"title": "The Man Who Wrote The Book On AI: 2030 Might Be The Point Of No Return!", "outlet": "The Diary Of A CEO", "year": 2025, "url": "https://podcasts.apple.com/au/podcast/the-man-who-wrote-the-book-on-ai-2030-might-be-the/id1291423644?i=1000739634021"}, {"title": "Stuart Russell: 'AI CEO Told Me Chernobyl-Level AI Event Might Be Our Only Hope' | For Humanity #72", "outlet": "For Humanity podcast (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=OGpTw4tthko", "youtube_id": "OGpTw4tthko"}, {"title": "Avoiding the Cliff of Uncontrollable AI (AGI Governance, Episode 9)", "outlet": "The Trajectory with Daniel Faggella (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=w0U5V86TMjo", "youtube_id": "w0U5V86TMjo"}, {"title": "The Edge Episode 29: Will AI Be Humanity's Last Act?", "outlet": "Cal Alumni Association - The Edge podcast", "year": 2025, "url": "https://alumni.berkeley.edu/california-magazine/the-edge-podcast/the-edge-episode-29-will-ai-be-humanitys-last-act-with-stuart-russell/"}, {"title": "3 principles for creating safer AI", "outlet": "TED", "year": 2017, "url": "https://www.ted.com/talks/stuart_russell_3_principles_for_creating_safer_ai"}], "links": {"website": "https://people.eecs.berkeley.edu/~russell/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Stuart_J._Russell", "github": "", "substack": ""}, "p_doom_or_stance": "Has not given a personal p(doom); argues the risk accepted by AI CEOs (he cites their 25-30% estimates) is millions of times too high and that governments must require provably safe systems (DOAC transcript, Dec 2025).", "honours": null, "photo": "stuart-russell.jpg"}, {"slug": "yoshua-bengio", "name": "Yoshua Bengio", "category": "academic-alignment", "current_role": "Full Professor, Université de Montréal; Co-President and Scientific Director, LawZero; Chair, International AI Safety Report (as of 2026)", "orgs_history": ["Founder and scientific director of Mila (until 2025)", "Université de Montréal faculty (1993-present)", "Launched LawZero (June 2025)", "Chair, International AI Safety Report (2024-)", "UN Independent International Scientific Panel on AI (2026)"], "country": "Canada", "known_for": "Turing Award-winning deep learning pioneer who pivoted to AI safety and founded LawZero to build a non-agentic 'Scientist AI'", "bio": "Yoshua Bengio (born 1964, Paris) is a Canadian computer scientist and one of the 'godfathers of deep learning', sharing the 2018 ACM Turing Award with Geoffrey Hinton and Yann LeCun. A professor at the Université de Montréal since 1993, he founded Mila, the Quebec AI Institute, and led it as scientific director until 2025. He is the most-cited computer scientist in the world and in November 2025 became the first AI researcher to pass one million Google Scholar citations. In 2023 he redirected his research toward AI safety. He chairs the International AI Safety Report, first published in January 2025, and in June 2025 launched LawZero, a Montreal nonprofit developing 'Scientist AI', a non-agentic system meant to make honest probabilistic predictions and act as a guardrail on untrusted AI agents. He has warned publicly about deception, reward hacking and self-preservation in frontier models, and in February 2026 was appointed to the UN's Independent International Scientific Panel on AI.", "key_ideas": ["Scientist AI (non-agentic, honest predictor)", "safe-by-design AI", "risks of agentic AI and self-preservation", "international scientific consensus on AI risk"], "key_works": [{"title": "International AI Safety Report", "year": 2025, "url": "https://internationalaisafetyreport.org/"}, {"title": "Superintelligent Agents Pose Catastrophic Risks: Can Scientist AI Offer a Safer Path?", "year": 2025, "url": "https://arxiv.org/abs/2502.15657"}, {"title": "Managing extreme AI risks amid rapid progress (Science)", "year": 2024, "url": "https://www.science.org/doi/10.1126/science.adn0117"}, {"title": "Introducing LawZero", "year": 2025, "url": "https://yoshuabengio.org/en/blog/introducing-lawzero"}], "quotes": [{"text": "I'm deeply concerned by the behaviors that unrestrained agentic AI systems are already beginning to exhibit—especially tendencies toward self-preservation and deception.", "context": "Blog post announcing LawZero, 3 June 2025", "source_url": "https://yoshuabengio.org/en/blog/introducing-lawzero"}, {"text": "Is it reasonable to train AI that will be more and more agentic while we do not understand their potentially catastrophic consequences?", "context": "Blog post announcing LawZero, 3 June 2025", "source_url": "https://yoshuabengio.org/en/blog/introducing-lawzero"}, {"text": "Most AI today is trained to act like us, to imitate, to please", "context": "LawZero announcement of the 'Safety from Honesty in a Disinterested AI Predictor' paper, 2026", "source_url": "https://lawzero.org/en/news/ai-predicts-has-no-hidden-agenda-lawzero-lays-out-formal-safety-case-its-scientist-ai"}, {"text": "Such a disinterested, scientist-like AI observes and analyzes rather than having hidden drives that can lead to scheming", "context": "LawZero announcement of its Scientist AI safety case, 2026", "source_url": "https://lawzero.org/en/news/ai-predicts-has-no-hidden-agenda-lawzero-lays-out-formal-safety-case-its-scientist-ai"}, {"text": "I should have thought of this 10 years ago. In fact, I could have, because I read some of the early works in AI safety.", "context": "Interview with Sigal Samuel, Vox Future Perfect, June 2025", "source_url": "https://www.vox.com/future-perfect/417087/ai-safety-yoshua-bengio-lawzero"}], "interviews": [{"title": "The Catastrophic Risks of AI — and a Safer Path", "outlet": "TED", "year": 2025, "url": "https://www.youtube.com/watch?v=qe9QSCF-d88", "youtube_id": "qe9QSCF-d88"}, {"title": "He's the godfather of AI. Now, he has a bold new plan to keep us safe from it.", "outlet": "Vox Future Perfect", "year": 2025, "url": "https://www.vox.com/future-perfect/417087/ai-safety-yoshua-bengio-lawzero"}, {"title": "Can AI safeguard us against AI? One of its Canadian pioneers thinks so", "outlet": "CBC Radio As It Happens", "year": 2025, "url": "https://www.cbc.ca/radio/asithappens/ai-safety-non-profit-1.7553839"}, {"title": "Yoshua Bengio Wants to Curb Harmful A.I. With LawZero", "outlet": "Observer (AI for Good Summit interview)", "year": 2025, "url": "https://observer.com/2025/07/yoshua-bengio-ai-for-good-summit-interview-lawzero/"}], "links": {"website": "https://yoshuabengio.org/", "x": "https://x.com/Yoshua_Bengio", "scholar": "https://scholar.google.com/citations?user=kukA0LcAAAAJ", "wikipedia": "https://en.wikipedia.org/wiki/Yoshua_Bengio", "github": "", "substack": ""}, "p_doom_or_stance": "Argues catastrophic and loss-of-control risks from agentic AI are serious enough to require safe-by-design, non-agentic systems and international coordination; no single p(doom) number verified.", "honours": null, "photo": "yoshua-bengio.jpg"}, {"slug": "geoffrey-hinton", "name": "Geoffrey Hinton", "category": "academic-alignment", "current_role": "University Professor Emeritus, University of Toronto; Chief Scientific Advisor, Vector Institute (as of 2026)", "orgs_history": ["Google Brain / Google VP & Engineering Fellow (2013-23, left to speak about AI risk)", "University of Toronto (1987-)", "Founded Gatsby Computational Neuroscience Unit, UCL (1998-2001)", "Co-founder, Vector Institute (2017)"], "country": "United Kingdom / Canada", "known_for": "'Godfather of AI', 2024 Nobel laureate in Physics, who quit Google in 2023 to warn about AI taking control", "bio": "Geoffrey Hinton (born 1947, London) is a British-Canadian computer scientist and cognitive psychologist whose work on neural networks underpins modern AI. He co-authored the 1986 paper that popularised backpropagation, and his lab's AlexNet (with Alex Krizhevsky and Ilya Sutskever) triggered the deep learning boom in 2012. He shared the 2018 Turing Award with Yoshua Bengio and Yann LeCun and the 2024 Nobel Prize in Physics with John Hopfield. From 2013 to 2023 he split his time between Google and the University of Toronto, where he is now University Professor Emeritus. In May 2023 he resigned from Google so he could 'freely speak out about the risks of AI', and has since warned about misuse, job loss and the existential risk of AI systems smarter than humans taking control. He uses the image of a 'cute tiger cub' for today's AI, has put the odds of AI takeover at roughly 10-20%, and in 2026 backed calls for AI developers to slow down.", "key_ideas": ["risk of superintelligent AI taking control", "digital intelligence may be a better form of intelligence", "need for AI companies to devote major compute to safety", "misuse risks (bio, cyber, disinformation)"], "key_works": [{"title": "Learning representations by back-propagating errors (Nature)", "year": 1986, "url": "https://www.nature.com/articles/323533a0"}, {"title": "ImageNet Classification with Deep Convolutional Neural Networks (AlexNet)", "year": 2012, "url": "https://papers.nips.cc/paper/4824-imagenet-classification-with-deep-convolutional-neural-networks"}, {"title": "Managing extreme AI risks amid rapid progress (Science, co-author)", "year": 2024, "url": "https://www.science.org/doi/10.1126/science.adn0117"}, {"title": "Nobel Prize in Physics 2024", "year": 2024, "url": "https://www.nobelprize.org/prizes/physics/2024/hinton/facts/"}], "quotes": [{"text": "There's risks that come from people misusing AI. Yeah, and that's most of the risks and all of the short term risks. And then there's risks that come from AI getting super smart and deciding it doesn't need us.", "context": "The Diary Of A CEO, June 2025 (transcript)", "source_url": "https://singjupost.com/transcript-of-godfather-of-ai-i-tried-to-warn-them-but-weve-already-lost-control/"}, {"text": "If you want to know what life's like when you're not the apex intelligence, ask a chicken", "context": "The Diary Of A CEO, June 2025 (transcript)", "source_url": "https://singjupost.com/transcript-of-godfather-of-ai-i-tried-to-warn-them-but-weve-already-lost-control/"}, {"text": "we're like somebody who has this really cute tiger cub. It's just such a cute tiger cub. Now, unless you can be very sure that it's not going to want to kill you when it's grown up, you should worry.", "context": "CBS Mornings interview with Brook Silva-Braga, April 2025 (transcript)", "source_url": "https://singjupost.com/transcript-of-brook-silva-braga-interviews-geoffrey-hinton-on-cbs-mornings/"}, {"text": "If we can't figure out a solution, we will be toast.", "context": "CNN State of the Union, 28 Dec 2025", "source_url": "https://transcripts.cnn.com/show/sotu/date/2025-12-28/segment/01"}, {"text": "A 10% chance seems not an unreasonable estimate to me, but nobody really knows how to give a sensible estimate,", "context": "BBC Newsnight, Sept 2026, on the chance AI wipes out humanity", "source_url": "https://www.businessinsider.com/geoffrey-hinton-godfather-of-ai-human-extinction-odds-2026-9"}], "interviews": [{"title": "Godfather of AI: I Tried to Warn Them, But We've Already Lost Control!", "outlet": "The Diary Of A CEO", "year": 2025, "url": "https://singjupost.com/transcript-of-godfather-of-ai-i-tried-to-warn-them-but-weve-already-lost-control/"}, {"title": "Brook Silva-Braga interviews Geoffrey Hinton", "outlet": "CBS Mornings", "year": 2025, "url": "https://singjupost.com/transcript-of-brook-silva-braga-interviews-geoffrey-hinton-on-cbs-mornings/"}, {"title": "Humans 'no longer needed' - Godfather of AI | 30 with Guyon Espiner", "outlet": "RNZ (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=uuOPOO90NBo", "youtube_id": "uuOPOO90NBo"}, {"title": "The 'Godfather of AI' says we can't afford to get it wrong", "outlet": "WBUR On Point", "year": 2025, "url": "https://www.wbur.org/onpoint/2025/12/29/godfather-of-ai-geoffrey-hinton"}, {"title": "Nobel Prize interview", "outlet": "NobelPrize.org", "year": 2024, "url": "https://www.nobelprize.org/prizes/physics/2024/hinton/interview"}], "links": {"website": "https://www.cs.toronto.edu/~hinton", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Geoffrey_Hinton", "github": "", "substack": ""}, "p_doom_or_stance": "~10-20% chance AI takes over: 'sort of 10 to 20% chance that these things will take over. But that's just a wild guess' (CBS, Apr 2025); 'A 10% chance seems not an unreasonable estimate' for extinction (BBC Newsnight, Sept 2026).", "honours": null, "photo": "geoffrey-hinton.jpg"}, {"slug": "eliezer-yudkowsky", "name": "Eliezer Yudkowsky", "category": "independent-org", "current_role": "Co-founder and Research Fellow, Machine Intelligence Research Institute (MIRI) (as of 2026)", "orgs_history": ["Co-founded the Singularity Institute, later MIRI (2000)", "Founded LessWrong (2009)", "Co-author, If Anyone Builds It, Everyone Dies (2025)"], "country": "United States", "known_for": "Founding thinker of AI alignment; argues building superintelligence with current methods would kill everyone", "bio": "Eliezer Yudkowsky (born 1979) is an American AI researcher and writer who co-founded the Machine Intelligence Research Institute (MIRI) in Berkeley, where he is a research fellow. Largely self-taught, he began writing in the early 2000s about 'Friendly AI' and the prospect of an intelligence explosion; this work influenced Nick Bostrom's Superintelligence and is discussed in Russell and Norvig's AI textbook. He founded the rationalist community blog LessWrong and wrote the essay series later collected as Rationality: From AI to Zombies, plus the fanfiction Harry Potter and the Methods of Rationality. In 2022 he published 'AGI Ruin: A List of Lethalities', and in a March 2023 TIME op-ed argued that a six-month pause was not enough and that large training runs should be shut down worldwide. In September 2025 he and MIRI president Nate Soares published If Anyone Builds It, Everyone Dies, a New York Times bestseller arguing that superhuman AI built with anything like current techniques would very likely cause human extinction.", "key_ideas": ["Friendly AI", "intelligence explosion", "orthogonality and instrumental convergence", "no retries on the 'first critical try'", "international halt to frontier AI development"], "key_works": [{"title": "If Anyone Builds It, Everyone Dies (with Nate Soares)", "year": 2025, "url": "https://ifanyonebuildsit.com/"}, {"title": "AGI Ruin: A List of Lethalities", "year": 2022, "url": "https://www.lesswrong.com/posts/uMQ3cqWDPHhjtiesc/agi-ruin-a-list-of-lethalities"}, {"title": "Pausing AI Developments Isn't Enough. We Need to Shut it All Down (TIME)", "year": 2023, "url": "https://time.com/6266923/ai-eliezer-yudkowsky-open-letter-not-enough/"}, {"title": "Artificial Intelligence as a Positive and Negative Factor in Global Risk", "year": 2008, "url": "https://intelligence.org/files/AIPosNegFactor.pdf"}], "quotes": [{"text": "the most likely result of building a superhumanly smart AI, under anything remotely like the current circumstances, is that literally everyone on Earth will die.", "context": "TIME op-ed, 29 March 2023", "source_url": "https://time.com/6266923/ai-eliezer-yudkowsky-open-letter-not-enough/"}, {"text": "the AI does not love you, nor does it hate you, and you are made of atoms it can use for something else.", "context": "TIME op-ed, 29 March 2023", "source_url": "https://time.com/6266923/ai-eliezer-yudkowsky-open-letter-not-enough/"}, {"text": "if you get that wrong on the first try, you do not get to learn from your mistakes, because you are dead.", "context": "TIME op-ed, 29 March 2023", "source_url": "https://time.com/6266923/ai-eliezer-yudkowsky-open-letter-not-enough/"}, {"text": "We are not ready. We are not on track to be significantly readier in the foreseeable future. If we go ahead on this everyone will die, including children who did not choose this and did not do anything wrong.", "context": "TIME op-ed, 29 March 2023", "source_url": "https://time.com/6266923/ai-eliezer-yudkowsky-open-letter-not-enough/"}, {"text": "we're going to be doing everything with metaphorical sigmoids on the first critical try.", "context": "'AGI Ruin: A List of Lethalities', LessWrong, 2022", "source_url": "https://www.lesswrong.com/posts/uMQ3cqWDPHhjtiesc/agi-ruin-a-list-of-lethalities"}], "interviews": [{"title": "#434 - Can We Survive AI? (with Nate Soares)", "outlet": "Making Sense with Sam Harris", "year": 2025, "url": "https://www.samharris.org/podcasts/making-sense-episodes/434-can-we-survive-ai"}, {"title": "Is AI Really Going to Kill Us All? (with Nate Soares)", "outlet": "American Compass (Oren Cass)", "year": 2025, "url": "https://www.commonplace.org/p/is-ai-really-going-to-kill-us-all"}, {"title": "The Doomers Who Insist AI Will Kill Us All", "outlet": "WIRED", "year": 2025, "url": "https://www.wired.com/story/the-doomers-who-insist-ai-will-kill-us-all/"}, {"title": "New book warns of threats to humanity from artificial intelligence", "outlet": "ABC News", "year": 2025, "url": "https://abcnews.com/video/125737441"}], "links": {"website": "https://www.yudkowsky.net/", "x": "https://x.com/ESYudkowsky", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Eliezer_Yudkowsky", "github": "", "substack": ""}, "p_doom_or_stance": "Extremely high: expects that building superhuman AI under current conditions means 'literally everyone on Earth will die' - 'Not as in maybe possibly some remote chance, but as in that is the obvious thing that would happen' (TIME, 2023). Calls for an indefinite worldwide moratorium.", "honours": null, "photo": "eliezer-yudkowsky.jpg"}, {"slug": "nate-soares", "name": "Nate Soares", "category": "independent-org", "current_role": "President, Machine Intelligence Research Institute (MIRI) (as of 2026)", "orgs_history": ["MIRI research fellow (2014), executive director/president (2015-)", "Google and Microsoft software engineer", "NIST research associate; US DoD contractor"], "country": "United States", "known_for": "MIRI president and co-author of If Anyone Builds It, Everyone Dies; co-coined 'AI alignment problem' via the Corrigibility paper", "bio": "Nate Soares is an American AI researcher and author who leads the Machine Intelligence Research Institute (MIRI) in Berkeley. After a B.S. in computer science and economics from George Washington University (2011), he worked at NIST, as a US Department of Defense contractor and at Microsoft and Google before joining MIRI as a research fellow in 2014. He was lead author of MIRI's 2015 technical agenda and co-authored 'Corrigibility' (2015), which he and Eliezer Yudkowsky credit with introducing the term 'AI alignment problem'. He became MIRI's executive director in 2015 and later its president. In September 2025 he and Yudkowsky published If Anyone Builds It, Everyone Dies, a New York Times bestseller arguing that modern AIs are 'grown rather than crafted', that superintelligence built with current techniques would very likely end humanity, and that an international ban on research toward superintelligence is needed. Since then he has promoted that case widely, including on Carnegie's The World Unpacked, the FLI podcast and Bloomberg's Odd Lots.", "key_ideas": ["corrigibility", "AIs are grown, not crafted", "international ban on superintelligence development", "no retries with superintelligence"], "key_works": [{"title": "If Anyone Builds It, Everyone Dies (with Eliezer Yudkowsky)", "year": 2025, "url": "https://ifanyonebuildsit.com/"}, {"title": "Corrigibility (AAAI workshop)", "year": 2015, "url": "https://intelligence.org/files/Corrigibility.pdf"}, {"title": "Ensuring smarter-than-human intelligence has a positive outcome (talk)", "year": 2017, "url": "https://intelligence.org/2017/04/12/ensuring/"}, {"title": "Replacing Guilt (essay series, Minding Our Way)", "year": 2015, "url": "https://mindingourway.com/guilt/"}], "quotes": [{"text": "modern AIs are grown rather than crafted. Human engineers are not carefully putting every line of code into the AIs while knowing what it does.", "context": "The World Unpacked podcast, Carnegie Endowment, Sept 2025", "source_url": "https://carnegieendowment.org/podcasts/the-world-unpacked/will-ai-kill-us-all-nate-soares-on-his-controversial-bestseller"}, {"text": "We collect huge amounts of computing power. We collect huge amounts of data. And we understand a process that tunes the numbers inside the computers according to each piece of data. But we don't understand the result of that tuning.", "context": "The World Unpacked podcast, Carnegie Endowment, Sept 2025", "source_url": "https://carnegieendowment.org/podcasts/the-world-unpacked/will-ai-kill-us-all-nate-soares-on-his-controversial-bestseller"}, {"text": "we don't see a lot of appetite for shutting down the race towards superintelligence, but that's in part, I think, because people don't know that the race is happening.", "context": "The World Unpacked podcast, Carnegie Endowment, Sept 2025", "source_url": "https://carnegieendowment.org/podcasts/the-world-unpacked/will-ai-kill-us-all-nate-soares-on-his-controversial-bestseller"}], "interviews": [{"title": "Will AI Kill Us All? Nate Soares on His Controversial Bestseller", "outlet": "The World Unpacked (Carnegie Endowment)", "year": 2025, "url": "https://carnegieendowment.org/podcasts/the-world-unpacked/will-ai-kill-us-all-nate-soares-on-his-controversial-bestseller"}, {"title": "Why Building Superintelligence Means Human Extinction", "outlet": "Future of Life Institute Podcast", "year": 2025, "url": "https://futureoflife.org/podcast/why-building-superintelligence-means-human-extinction-with-nate-soares/"}, {"title": "#434 - Can We Survive AI? (with Eliezer Yudkowsky)", "outlet": "Making Sense with Sam Harris", "year": 2025, "url": "https://www.samharris.org/podcasts/making-sense-episodes/434-can-we-survive-ai"}, {"title": "Nate Soares on How AI Really Could Kill Us All", "outlet": "Bloomberg Odd Lots", "year": 2026, "url": "https://podcasts.apple.com/us/podcast/nate-soares-on-how-ai-really-could-kill-us-all/id1056200096?i=1000795909362"}], "links": {"website": "https://mindingourway.com/", "x": "https://x.com/So8res", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Nate_Soares", "github": "", "substack": ""}, "p_doom_or_stance": "Argues superintelligence built with anything like current techniques would very likely cause human extinction; calls for an international ban on research toward superintelligence (FLI podcast, Sept 2025; book).", "honours": null, "photo": "nate-soares.jpg"}]);
